parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "pertinent": {"type": "boolean", "description": "true si le mail concerne le BDE ou un partenariat"},
    "categorie": {"type": "string", "enum": ["partenariat", "sponsoring", "evenement", "question_bde", "autre_pertinent", "newsletter", "publicite", "notification", "spam", "hors_sujet"]},
    "raison": {"type": "string", "description": "phrase courte en français"}
  },
  "required": ["pertinent", "categorie", "raison"]
}

parameters.jsCode:
// Sortie validée par le Structured Output Parser
const o = $input.first().json.output || {};
const mail = $('K0 - Entrée Mail').first().json;
return [{
  json: {
    pertinent: o.pertinent === true,
    categorie: String(o.categorie || 'non_classe'),
    raison: String(o.raison || ''),
    prospect_email: mail.prospect_email,
    subject: mail.subject,
    validated: true
  }
}];

// Fallback : IA indisponible ou sortie non conforme au schéma -> ticket par précaution (fail-open)
const mail = $('K0 - Entrée Mail').first().json;
return [{
  json: {
    pertinent: true,
    categorie: 'non_classe',
    raison: 'Classification IA impossible, ticket créé par précaution',
    prospect_email: mail.prospect_email,
    subject: mail.subject,
    validated: false
  }
}];
